/// <summary>
/// The <c>AVABPJobProtService</c> class is the service class for <c>BP-CleanUps</c>
/// </summary>
class AVABPJobProtService extends SysOperationServiceBase
{
    AVABPCleanUpContract    dataContract;
    boolean                 lJobMode;

}

Method.Source:
/// <summary>
///    AVA <c>runService</c> method.
/// </summary>
/// <param name="_dataContract">
///    <c>AVABPCleanUpContract</c> as type
/// </param>
void runService(AVABPCleanUpContract _dataContract)
{
    dataContract = _dataContract;

    this.deleteEntries();
}

 /// <summary>
 ///     AVA <c>deleteEntries</c> method.
 /// </summary>
 void deleteEntries()
 {
     NDX_KBVJobProt  kbvJobProt;

     UtcDateTime     cleanUpDateTime;
     date            tmpDate;

     cleanUpDateTime = DateTimeUtil::newDateTime(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()), 0);
     cleanUpDateTime = DateTimeUtil::addDays(cleanUpDateTime, -dataContract.parmAVABPOlderThanNumberOfDays());
     tmpDate         = DateTimeUtil::date(cleanUpDateTime);
     cleanUpDateTime = datetoendUtcDateTime(tmpDate, DateTimeUtil::getUserPreferredTimeZone());
     /*
     kbvJobProt.skipDataMethods(true);
     kbvJobProt.skipDeleteActions(true);
     */

     delete_from kbvJobProt
     where kbvJobProt.StartDateTime <= cleanUpDateTime;
}
